name: Dependabot Auto Merge

on:
  pull_request_target:
    types: [opened, synchronize, reopened]
  workflow_run:
    workflows: ["Only CI/CT"]
    types: [completed]

permissions:
  pull-requests: write
  checks: read
  contents: read
  statuses: read

jobs:
  dependabot_auto_merge:
    if: github.event.pull_request.head.repo.full_name == github.repository
    runs-on: ubuntu-latest
    steps:
      - name: Auto merge Dependabot PRs
        uses: actions/github-script@v6
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const eventName = github.context.eventName;
            let prNumber;

            if (eventName === 'pull_request_target') {
              prNumber = github.context.payload.pull_request.number;
            } else if (eventName === 'workflow_run') {
              // Wait a bit for status propagation
              await new Promise(r => setTimeout(r, 5000));
              if (!github.context.payload.workflow_run.pull_requests || github.context.payload.workflow_run.pull_requests.length === 0) {
                console.log('No pull request found in workflow_run event.');
                return;
              }
              prNumber = github.context.payload.workflow_run.pull_requests[0].number;
            } else {
              console.log('Unsupported event:', eventName);
              return;
            }

            const { owner, repo } = github.context.repo;

            // Get PR details
            const { data: pr } = await github.rest.pulls.get({
              owner,
              repo,
              pull_number: prNumber
            });

            // Check if PR is from dependabot[bot]
            if (pr.user.login !== 'dependabot[bot]') {
              console.log(`PR #${prNumber} is not from dependabot[bot]. Skipping.`);
              return;
            }

            // Get combined status
            const { data: combinedStatus } = await github.rest.repos.getCombinedStatusForRef({
              owner,
              repo,
              ref: pr.head.sha
            });

            if (combinedStatus.state !== 'success') {
              console.log(`Combined status is ${combinedStatus.state}. Skipping merge.`);
              return;
            }

            // Get check runs
            const { data: checkRunsData } = await github.rest.checks.listForRef({
              owner,
              repo,
              ref: pr.head.sha
            });

            if (!checkRunsData.total_count || checkRunsData.total_count === 0) {
              console.log('No check runs found. Skipping merge.');
              return;
            }

            // Verify all check runs are successful
            const failedChecks = checkRunsData.check_runs.filter(cr => cr.status === 'completed' && cr.conclusion !== 'success');
            if (failedChecks.length > 0) {
              console.log(`Found ${failedChecks.length} failed or cancelled checks. Skipping merge.`);
              return;
            }

            // Approve the PR
            try {
              await github.rest.pulls.createReview({
                owner,
                repo,
                pull_number: prNumber,
                event: 'APPROVE'
              });
              console.log(`Approved PR #${prNumber}.`);
            } catch (e) {
              console.log(`Error approving PR #${prNumber}: ${e.message}`);
            }

            // Merge the PR
            try {
              await github.rest.pulls.merge({
                owner,
                repo,
                pull_number: prNumber,
                merge_method: 'squash'
              });
              console.log(`Merged PR #${prNumber} with squash.`);
            } catch (e) {
              console.log(`Error merging PR #${prNumber}: ${e.message}`);
            }
